Now, implement a global static with runtime initialization. Use `std::sync::LazyLock` (stable since 1.80). This is the idiomatic choice for a global static whose initialization requires runtime computation.

Let me write main.rs demonstrating it.

```rust
use std::sync::LazyLock;

static CONFIG: LazyLock<Config> = LazyLock::new(|| Config::from_env());

struct Config {
    greeting: String,
    worker_count: usize,
}

impl Config {
    fn from_env() -> Self {
        let greeting = std::env::var("APP_GREETING").unwrap_or_else(|_| "Hello, world!".to_string());
        let worker_count = std::env::var("APP_WORKERS")
            .ok()
            .and_then(|v| v.parse().ok())
            .unwrap_or_else(|| {
                std::thread::available_parallelism().map(|n| n.get()).unwrap_or(1)
            });
        Config { greeting, worker_count }
    }
}

fn main() {
    println!("{} ({} workers)", CONFIG.greeting, CONFIG.worker_count);
}
```

